#### Fix 2
fix: late warp quad clipped by orthographic camera bounds

**Fix:** Replace:
```
  warpCamera = new THREE.OrthographicCamera(-aspect/2, aspect/2, 1/2, -1/2, near, far);
```

with:
```
  warpCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, near, far);
```

#### Fix 3
fix: frame time profiling measures simulation step not render interval

**Fix:** Apply patch:
```diff
--- js/fps.js
+++ js/fps.js
@@ -1190,11 +1190,6 @@ function animate() {

   const now  = Date.now();
-  frameTimes.push(now - last_update_time);
-  if(frameTimes.length > numFrameTimes) {
-    frameTimes.shift();
-    frameTimeValid = true;
-  }

   rawInputState.update();
   fpsControls.processDelayedEvents(rawInputState.getDelayedFrameEvents());
@@ -1258,6 +1253,13 @@ function animate() {
   // Handle rendering here
   if (!config.render.setFPS || (now - last_render_time >= 0.95 * (1000 / config.render.frameRate))) {

+    // Profile actual render frame intervals, not simulation sub-steps
+    if (last_render_time > 0) {
+      frameTimes.push(now - last_render_time);
+      if(frameTimes.length > numFrameTimes) frameTimes.shift();
+      frameTimeValid = true;
+    }
+
      // Scale reticle based on time since last shot
      if(now - last_fire_time < 1000 * config.reticle.shrinkTime){     
       const scale = config.reticle.expandedScale * (1  - (now - last_fire_time) / (1000 * config.reticle.shrinkTime)) + 1;
```

